  output.materialSlot = vertexMetadata.w;
  output.position = rtcTile.viewProjection * rtcWorldPos;
  output.color = instance.color * input.vertexColor;
  output.meshIndex = vertexMetadata.x;
  output.sectionPos = (rtcTile.viewMatrix * rtcWorldPos).xyz;
  output.clipBoxPos = instanceClipBoxPosition(instance, rtcWorldPos, instance.flags.x);
  output.rtcPos = rtcWorldPos.xyz / rtcWorldPos.w;
