      this.techniqueWithFramesAndNormals = techniqueOrVariants.withFramesAndNormals ?? null;
      this.techniqueWithFramesAndUVs = techniqueOrVariants.withFramesAndUVs ?? null;
      this.techniqueWithFramesNormalsAndUVs = techniqueOrVariants.withFramesNormalsAndUVs ?? null;
      this.techniqueWithFramesAndTriplanar = techniqueOrVariants.withFramesAndTriplanar ?? null;
      this.techniqueWithFramesNormalsAndTriplanar = techniqueOrVariants.withFramesNormalsAndTriplanar ?? null;
